// Helper encoder: read a JPEG, set up ImageBundle via the custom (libjpeg-free)
// reader, encode a VarDCT JXL codestream, append 4 fuzzer flag bytes.
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <vector>
#include <cstdint>

#include "lib/jxl/base/span.h"
#include "lib/jxl/base/status.h"
#include "lib/jxl/codec_in_out.h"
#include "lib/jxl/color_encoding_internal.h"
#include "lib/jxl/enc_file.h"
#include "lib/jxl/enc_params.h"
#include "lib/jxl/image_bundle.h"
#include "lib/jxl/jpeg/enc_jpeg_data.h"
#include "lib/jxl/thread_parallel_runner.h"

using namespace jxl;

int main(int argc, char** argv) {
  if (argc < 4) {
    fprintf(stderr, "usage: %s in.jpg out.jxl [flags_u32]\n", argv[0]);
    return 2;
  }
  FILE* f = fopen(argv[1], "rb");
  if (!f) { perror("fopen"); return 1; }
  fseek(f, 0, SEEK_END);
  long sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  std::vector<uint8_t> jpg(sz);
  if (fread(jpg.data(), 1, sz, f) != (size_t)sz) { perror("fread"); return 1; }
  fclose(f);

  uint32_t flags = 0;
  if (argc >= 4) flags = (uint32_t)strtoul(argv[3], nullptr, 0);

  CodecInOut io;
  {
    Status st = jpeg::DecodeImageJPG(Span<const uint8_t>(jpg.data(), jpg.size()), &io);
    if (!st) { fprintf(stderr, "jpeg decode failed\n"); return 1; }
  }
  fprintf(stderr, "dims=%zux%zu cs444?=%d color_xform=%d\n",
          io.xsize(), io.ysize(),
          io.Main().chroma_subsampling.Is444() ? 1 : 0,
          (int)io.Main().color_transform);

  CompressParams cparams;
  cparams.speed_tier = SpeedTier::kFalcon;  // faster encode
  cparams.butteraugli_distance = 1.0f;

  PaddedBytes compressed;
  PassesEncoderState pes;
  AuxOut aux;
  ThreadPool* pool = ThreadPoolInner(nullptr, 8);
  Status ok = EncodeFile(cparams, &io, &pes, &compressed, &aux, pool);
  if (pool) ThreadPoolDestroy(pool);
  if (!ok) { fprintf(stderr, "encode failed\n"); return 1; }

  // Append 4 flag bytes (little-endian uint32) for djxl_fuzzer.
  for (int i = 0; i < 4; i++) compressed.push_back((flags >> (8 * i)) & 0xff);

  FILE* o = fopen(argv[2], "wb");
  if (!o) { perror("fopen out"); return 1; }
  fwrite(compressed.data(), 1, compressed.size(), o);
  fclose(o);
  fprintf(stderr, "wrote %zu bytes\n", compressed.size());
  return 0;
}
EOF
